## What are you doing?
If you add a scope to your association, you will get the search query filter as the value of the attribute after a find. This is fine if the scoped filter is a value, but not if it is something more complicated, like an object with a symbol. The actual filter seems to be working though, so perhaps just the population of the model.

```js
'use strict';

const Sequelize = require('sequelize');
const Op = Sequelize.Op;

let Model, ModelB;

async function test(useEnum) {
new Sequelize('test', 'user', 'user', {
    host: '127.0.0.1',
    dialect: 'postgresql',
    "quoteIdentifiers": true, 
    "underscored": true
  });

  Model = db.define('Model', { }, {});
  ModelB = db.define('ModelB', { int_attr: Sequelize.INTEGER, model_id : Sequelize.INTEGER }, {});

  Model.hasMany(ModelB, {as: 'working', scope: {int_attr:0}, foreignKey: 'model_id'});
  Model.hasMany(ModelB, {as: 'broken', scope: {int_attr:{[Op.not]:0}}, foreignKey: 'model_id'});
  ModelB.belongsTo(Model, {foreignKey: 'model_id'});

  await db.sync({ force: true });

  await populateDb();

  const t1 = await Model.findOne({where: {id:1}, include:[
    {
      
      model:ModelB,
      as: 'working'
    },
    {
      
      model:ModelB,
      as: 'broken'
    }
  ]});

  console.log('t1', t1.working[0].int_attr)
  console.log('t1', t1.broken[0].int_attr)

  await db.close();
}

async function populateDb() {
  const model = await Model.create({ id:1});
  const modelB1 = await ModelB.create({ int_attr:0, model_id:model.id });
  const modelB2 = await ModelB.create({ int_attr:1, model_id:model.id });
}

async function main() {
  try {
    console.log('Bad sql');
    await test();
  } catch (err) {
    console.error(err);
    process.exit(1);
  }
}

main();
```

## What do you expect to happen?
I wanted the values of int_attr to be 0 and 1 after the find

## What is actually happening?
The values of int_attr was 0 and { [Symbol(not)]: 0 } after the find

